import { tokenizeEdifact } from '@/lib/ediel/core/edifactTokenizer'
import { parseUnh } from '@/lib/ediel/core/unh'

export type AperakSourceFamily = 'PRODAT' | 'UTILTS' | 'UTILTS_ERR'
export type AperakSourceProfileInput = {
  /** Correlated original message family, not a route or tenant default. */
  sourceMessageFamily?: string | null
  /** Exact single-message payload, when available. Metadata cannot override it. */
  rawPayload?: string | null
}

export class AperakSourceProfileError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'AperakSourceProfileError'
  }
}

export function aperakAssociationForSource(source: AperakSourceFamily): 'E2SE6A' | 'E5SE5A' {
  return source === 'PRODAT' ? 'E2SE6A' : 'E5SE5A'
}

/** Select only a protocol profile. This is not original-message correlation,
 * permission evidence, a guide revision, or a successful syntax validation. */
export function resolveAperakSourceFamily(input: AperakSourceProfileInput): AperakSourceFamily {
  const supplied = String(input.sourceMessageFamily ?? '').trim().toUpperCase()
  if (supplied && !['PRODAT', 'UTILTS', 'UTILTS_ERR'].includes(supplied)) {
    throw new AperakSourceProfileError(`ediel_aperak_source_family_required:${supplied}`)
  }
  const source = supplied as AperakSourceFamily | ''
  let wireSource: 'PRODAT' | 'UTILTS' | null = null
  if (input.rawPayload !== undefined && input.rawPayload !== null) {
    if (!input.rawPayload.trim()) throw new AperakSourceProfileError('ediel_aperak_wire_profile_empty')
    let tokens: ReturnType<typeof tokenizeEdifact>
    try {
      tokens = tokenizeEdifact(input.rawPayload)
    } catch {
      throw new AperakSourceProfileError('ediel_aperak_wire_parse_failed')
    }
    const headers = tokens.segments.filter((segment) => segment.tag === 'UNH')
    if (headers.length !== 1) {
      throw new AperakSourceProfileError(`ediel_aperak_wire_header_count:${headers.length}`)
    }
    // Use the shared release-aware component parser. Do not strip punctuation,
    // split decoded strings twice, or take only the first of several UNH rows.
    const header = parseUnh(headers[0], tokens.una)
    if (header?.messageType === 'APERAK' && header.version === 'D' && header.controllingAgency === 'UN') {
      if (header.release === '96A' && header.associationAssignedCode === 'E2SE6A') wireSource = 'PRODAT'
      if (header.release === '04A' && header.associationAssignedCode === 'E5SE5A') wireSource = 'UTILTS'
    }
    if (!wireSource) throw new AperakSourceProfileError('ediel_aperak_wire_profile_invalid')
    if (source && aperakAssociationForSource(source) !== aperakAssociationForSource(wireSource)) {
      throw new AperakSourceProfileError(`ediel_aperak_source_profile_mismatch:${source}:${wireSource}`)
    }
  }
  if (source) return source
  if (wireSource) return wireSource
  throw new AperakSourceProfileError('ediel_aperak_source_family_required:missing')
}

